svg.script:
(function () {
  "use strict";

  // Resolve index.html from the same jsDelivr package version as this SVG.
  // That means @main stays live, while @v1.0.3 stays pinned to that release.
  const base = new URL(".", window.location.href).href;
  const source = new URL("index.html", base).href;
  const mainBase = "https://cdn.jsdelivr.net/gh/Shazam123abc/sh0zy@main/";
  const frame = document.getElementById("sift-site");
  const errorPanel = document.getElementById("sift-load-error");
  const errorMessage = document.getElementById("sift-load-error-message");

  function showError(message) {
    errorMessage.textContent = message;
    errorPanel.style.display = "block";
  }

  fetch(source, { cache: "no-cache" })
    .then(function (response) {
      if (!response.ok) {
        throw new Error("The SIFT HTML returned HTTP " + response.status + ".");
      }
      return response.text();
    })
    .then(function (html) {
      if (!/<html[\s>]/i.test(html) || !/<body[\s>]/i.test(html)) {
        throw new Error("The repository did not return the expected index.html page.");
      }

      // srcdoc inherits this SVG document's origin. Add the repository root
      // as its base so relative links and assets resolve like index.html.
      // Keep the page's data, app pages, and relative assets on the same
      // package version as this SVG, rather than always forcing @main.
      html = html.split(mainBase).join(base);
      const baseTag = '<base href="' + base + '">';
      if (/<head(?:\s[^>]*)?>/i.test(html)) {
        html = html.replace(/<head(?:\s[^>]*)?>/i, function (head) {
          return head + baseTag;
        });
      } else {
        html = html.replace(/<html(?:\s[^>]*)?>/i, function (root) {
          return root + "<head>" + baseTag + "</head>";
        });
      }

      frame.srcdoc = html;
    })
    .catch(function (error) {
      showError(error && error.message
        ? error.message
        : "Could not fetch the SIFT website. Check the network and try again.");
    });
})();
